changeSet.sql:
INSERT INTO permissions (name, description)
VALUES ('plugin_deviceenroll_access', 'Can manage automatic device numbering rules');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE id IN (1, 2);

DELETE FROM plugin_deviceenroll_rule WHERE groupId IS NULL;

ALTER TABLE plugin_deviceenroll_rule
    DROP CONSTRAINT plugin_deviceenroll_rule_pr_key;
ALTER TABLE plugin_deviceenroll_rule ADD COLUMN id SERIAL;
ALTER TABLE plugin_deviceenroll_rule
    ADD CONSTRAINT plugin_deviceenroll_rule_pr_key PRIMARY KEY (id);

ALTER TABLE plugin_deviceenroll_rule ALTER COLUMN groupId SET NOT NULL;
ALTER TABLE plugin_deviceenroll_rule
    DROP CONSTRAINT IF EXISTS plugin_deviceenroll_rule_groupid_fkey;
ALTER TABLE plugin_deviceenroll_rule
    ADD CONSTRAINT plugin_deviceenroll_rule_group_fk
    FOREIGN KEY (groupId) REFERENCES groups (id) ON DELETE CASCADE;
ALTER TABLE plugin_deviceenroll_rule
    ADD CONSTRAINT plugin_deviceenroll_rule_group_uniq UNIQUE (groupId);
